<script setup lang="ts">const shop=useShop();const coupon=ref('');const applied=ref(false);const discount=computed(()=>applied.value&&coupon.value.trim().toUpperCase()==='VY10'?shop.cartSubtotal*.1:0);const shipping=computed(()=>shop.cartSubtotal-discount.value>=75||shop.cartSubtotal===0?0:4.5);const total=computed(()=>shop.cartSubtotal-discount.value+shipping.value);function apply(){if(coupon.value.trim().toUpperCase()==='VY10'){applied.value=true;shop.notify('VY10 applied — 10% off!')}else{applied.value=false;shop.notify('That demo code is not valid. Try VY10.','error')}}function lineProduct(id:string){return shop.productById(id)}</script>
<template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10 sm:py-14"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Your edit</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Shopping bag<span class="text-brand">.</span></h1><div v-if="shop.cart.length" class="mt-8 grid gap-10 lg:grid-cols-[1fr_340px]"><section><div v-for="line in shop.cart" :key="line.key" class="flex gap-4 border-b border-gray-100 py-5 first:border-t"><NuxtLink :to="`/products/${lineProduct(line.productId)?.slug}`" class="h-32 w-24 shrink-0 overflow-hidden rounded-xl bg-mist"><img v-if="lineProduct(line.productId)" :src="lineProduct(line.productId)!.images[0]" :alt="lineProduct(line.productId)!.name" class="h-full w-full object-cover"></NuxtLink><div class="flex min-w-0 flex-1 flex-col"><div class="flex justify-between gap-3"><div><NuxtLink :to="`/products/${lineProduct(line.productId)?.slug}`" class="text-sm font-semibold">{{ lineProduct(line.productId)?.name }}</NuxtLink><p class="mt-1 text-xs text-gray-500">{{ line.color }} · Size {{ line.size }}</p></div><p class="shrink-0 text-sm font-bold">${((lineProduct(line.productId)?shop.price(lineProduct(line.productId)!):0)*line.quantity).toFixed(2)}</p></div><div class="mt-auto flex items-center justify-between pt-3"><div class="flex items-center rounded-full border border-gray-200"><button class="px-3 py-2" @click="shop.updateQuantity(line.key,line.quantity-1)">−</button><span class="min-w-5 text-center text-xs">{{ line.quantity }}</span><button class="px-3 py-2" @click="shop.updateQuantity(line.key,line.quantity+1)">+</button></div><button class="text-xs text-gray-500 underline underline-offset-4 hover:text-red-600" @click="shop.removeFromCart(line.key)">Remove</button></div></div></div><button class="mt-5 text-xs font-bold uppercase tracking-wider text-gray-500 hover:text-red-600" @click="shop.clearCart();applied=false">Clear bag</button></section><aside class="h-fit rounded-2xl bg-mist p-6"><h2 class="text-lg font-semibold">Order summary</h2><div class="mt-5 flex gap-2"><input v-model="coupon" class="min-w-0 flex-1 rounded-full border border-gray-200 bg-white px-4 py-3 text-xs outline-none focus:border-brand" placeholder="Discount code"><button class="rounded-full bg-ink px-4 text-xs font-bold text-white" @click="apply">Apply</button></div><p class="mt-2 text-[10px] text-gray-500">Demo code: VY10 for 10% off.</p><div class="mt-6 space-y-3 border-t border-gray-200 pt-5 text-sm"><div class="flex justify-between"><span class="text-gray-500">Subtotal</span><span>${{ shop.cartSubtotal.toFixed(2) }}</span></div><div v-if="discount" class="flex justify-between text-green-700"><span>Discount</span><span>−${{ discount.toFixed(2) }}</span></div><div class="flex justify-between"><span class="text-gray-500">Shipping</span><span>{{ shipping===0?'Free':'$'+shipping.toFixed(2) }}</span></div><p v-if="shop.cartSubtotal-discount<75" class="text-xs text-gray-500">You're ${{ Math.max(0,75-(shop.cartSubtotal-discount)).toFixed(2) }} away from free shipping.</p><div class="flex justify-between border-t border-gray-200 pt-4 text-base font-bold"><span>Total</span><span>${{ total.toFixed(2) }}</span></div></div><NuxtLink :to="{path:'/checkout',query:applied?{coupon:'VY10'}:{}}" class="mt-6 flex w-full justify-center rounded-full bg-brand px-5 py-4 text-xs font-bold uppercase tracking-wider text-white transition hover:bg-ink">Continue to checkout ↗</NuxtLink><NuxtLink to="/shop" class="mt-4 block text-center text-xs font-semibold text-gray-500 underline underline-offset-4">Continue shopping</NuxtLink><p class="mt-5 text-center text-[10px] leading-5 text-gray-500">Frontend demo only. No payment will be taken.</p></aside></div><div v-else class="mt-8"><EmptyState title="Your bag is taking a little break" description="You haven't added anything yet. Find pieces that feel like you." to="/shop" action-label="Explore the collection"/></div></div></template>
